# Discovery edits are scoped and idempotent; no fees, forms or existing metadata change.
blog_file=ROOT/'blog.html';blog=blog_file.read_text(encoding='utf-8')
feature=f'''<section class="section alt" aria-labelledby="latest-research-title"><div class="container"><div class="section-head"><p class="eyebrow">New evidence audit · November 2, 2026</p><h2 id="latest-research-title">Staff names, review requests and what the evidence measures</h2><p>15 source estimates, three original graphs and an open dataset connect the study findings with Google’s current policy.</p></div><div class="card-grid two-column"><article class="card" style="align-self:center;min-height:0"><h3>{H1}</h3><p>A named review cannot reveal the request behind it. Compare the study’s review-level and business-level estimates, then check the growth arithmetic.</p><a href="google-reviews-staff-names-study.html">Read the evidence audit →</a></article><figure class="data-figure"><a href="google-reviews-staff-names-study.html"><img src="google-staff-name-business-controls.svg" width="1200" height="780" loading="lazy" decoding="async" alt="Three source business-level estimates change with adjustment; the review request is unobserved."></a><figcaption>Original ReviewsBoost graph; source estimates attributed to Reviewflowz and Cartelis.</figcaption></figure></div><p>Earlier research: <a href="google-review-removal-language-study.html">language and moderation accuracy</a> · <a href="google-review-replies-removal-bias-study.html">reply timing and time-order bias</a> · <a href="google-review-removal-time-study.html">what removal timing measures</a>.</p></div></section>'''
pattern=r'<section class="section alt" aria-labelledby="latest-research-title">[\s\S]*?</section>'
assert re.search(pattern,blog),'Missing blog feature slot';blog=re.sub(pattern,lambda _:feature,blog,count=1)
def update_schema(match):
    schema=json.loads(match[1])
    for node in schema.get('@graph',[]):
        if node.get('@type')=='CollectionPage':node['dateModified']=DATE
        if node.get('@type')=='ItemList':
            items=node['itemListElement']
            if not any(item.get('url')==URL for item in items):items.append({'@type':'ListItem','position':len(items)+1,'name':H1,'url':URL})
            node['numberOfItems']=len(items)
    return '<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False,indent=2).replace('<',chr(92)+'u003c')+'</script>'
blog=re.sub(r'<script type="application/ld\+json">([\s\S]*?)</script>',update_schema,blog,count=1)
blog_file.write_text(blog,encoding='utf-8')

home_file=ROOT/'index.html';home=home_file.read_text(encoding='utf-8')
marker=r'<!-- staff-name-study discovery start -->[\s\S]*?<!-- staff-name-study discovery end -->'
discovery='<!-- staff-name-study discovery start --><p class="rate-methodology">New research: <a href="google-reviews-staff-names-study.html">Staff names in Google reviews: study findings, request policy and three original graphs</a>.</p><!-- staff-name-study discovery end -->'
if re.search(marker,home):home=re.sub(marker,lambda _:discovery,home,count=1)
else:
    anchor='<!-- language-study discovery start -->';assert anchor in home
    home=home.replace(anchor,discovery+'\n            '+anchor,1)
    home=home.replace('Latest research: <a href="google-review-removal-language-study.html">','Earlier research: <a href="google-review-removal-language-study.html">',1)
home_file.write_text(home,encoding='utf-8')

guide_file=ROOT/'get-more-google-reviews.html';guide=guide_file.read_text(encoding='utf-8')
if 'google-reviews-staff-names-study.html' not in guide:
    anchor='<h3>6. Prepare staff</h3>';assert anchor in guide
    guide=guide.replace(anchor,anchor+'\n          <p>Should you ask customers to name an employee? Our <a href="google-reviews-staff-names-study.html">staff-name evidence audit</a> separates voluntary mentions from directed requests and checks what the published study actually measures.</p>',1)
    guide_file.write_text(guide,encoding='utf-8')

sitemap_file=ROOT/'sitemap.xml';sitemap=sitemap_file.read_text(encoding='utf-8')
sitemap=re.sub(r'(<loc>https://reviewsboost\.ca/blog\.html</loc>\s*<lastmod>)[^<]+',lambda m:m[1]+DATE,sitemap)
entry='<url><loc>'+URL+'</loc><lastmod>'+DATE+'</lastmod>'+''.join('<image:image><image:loc>https://reviewsboost.ca/'+name+'.png</image:loc></image:image>' for name,_,_ in images)+'</url>'
pattern=r'<url>\s*<loc>'+re.escape(URL)+r'</loc>[\s\S]*?</url>'
if re.search(pattern,sitemap):sitemap=re.sub(pattern,lambda _:entry,sitemap,count=1)
else:sitemap=sitemap.replace('</urlset>','  '+entry+'\n</urlset>')
sitemap_file.write_text(sitemap,encoding='utf-8')

feed_file=ROOT/'feed.xml';feed=feed_file.read_text(encoding='utf-8')
feed=re.sub(r'<lastBuildDate>[^<]+</lastBuildDate>','<lastBuildDate>Mon, 02 Nov 2026 00:00:00 -0500</lastBuildDate>',feed,count=1)
item=f'<item><title>{esc(H1)}</title><link>{URL}</link><guid isPermaLink="true">{URL}</guid><pubDate>Mon, 02 Nov 2026 00:00:00 -0500</pubDate><description>{esc(DESC)}</description></item>'
if URL not in feed:
    assert '<item>' in feed;feed=feed.replace('<item>',item+'\n    <item>',1)
feed_file.write_text(feed,encoding='utf-8')
print('Built the staff-name study, blog feature/ItemList, contextual discovery links, RSS and image sitemap; no deployment.')
